"""Board representation, parsing, rendering and validation.

A board is 81 digits, 0 meaning empty. We keep two views of it:

* the *string* form -- 81 characters, the interchange format used by every
  public sudoku dataset, and what the CLI accepts;
* the *array* form -- a ``numpy`` ``uint8`` array of shape ``(81,)``, which is
  what the solvers and (after encoding) the models consume.

Keeping the canonical form flat rather than 9x9 matters later: the models in
Stage 2 treat the grid as a sequence of 81 tokens, and reshaping to ``(9, 9)``
is a view, not a copy.
"""

from __future__ import annotations

import numpy as np

from .units import BOX, N, N_CELLS, UNITS

EMPTY = 0
#: Characters that a parser should treat as "no digit here".
BLANK_CHARS = frozenset({"0", ".", "_", "*"})
#: Characters that are grid decoration, not cells. Note ``-`` is layout, not a
#: blank: :func:`render` draws separator rules with it, and we want a rendered
#: grid to survive a round trip back through :func:`from_string`.
LAYOUT_CHARS = frozenset({"|", "+", "-"})


class BoardError(ValueError):
    """Raised when input cannot be parsed as a board."""


def from_string(text: str) -> np.ndarray:
    """Parse 81 characters into a ``uint8`` array of shape ``(81,)``.

    Accepts any of :data:`BLANK_CHARS` for an empty cell, and ignores
    newlines and pipes so that a pretty-printed grid can be pasted back in.
    """
    cleaned = [
        ch for ch in text if not ch.isspace() and ch not in LAYOUT_CHARS
    ]
    digits = []
    for ch in cleaned:
        if ch in BLANK_CHARS:
            digits.append(EMPTY)
        elif ch.isdigit():
            digits.append(int(ch))
        else:
            raise BoardError(f"unexpected character {ch!r} in board string")
    if len(digits) != N_CELLS:
        raise BoardError(f"expected {N_CELLS} cells, got {len(digits)}")
    return np.array(digits, dtype=np.uint8)


def to_string(board: np.ndarray) -> str:
    """Render a board back to its 81-character interchange form."""
    return "".join(str(int(v)) for v in board)


def render(board: np.ndarray, blank: str = ".") -> str:
    """Render a board as a human-readable grid with box separators."""
    lines = []
    for r in range(N):
        if r and r % BOX == 0:
            lines.append("------+-------+------")
        cells = []
        for c in range(N):
            if c and c % BOX == 0:
                cells.append("|")
            value = int(board[r * N + c])
            cells.append(blank if value == EMPTY else str(value))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def is_complete(board: np.ndarray) -> bool:
    """True if every cell is filled (says nothing about correctness)."""
    return not bool((board == EMPTY).any())


def find_conflicts(board: np.ndarray) -> list[tuple[int, int]]:
    """Return every pair of cells that share a unit and hold the same digit.

    An empty list means the board is *consistent* -- it breaks no constraint.
    A consistent board may still be incomplete, and an incomplete consistent
    board may still be unsolvable, which is exactly why Lesson 03 exists.
    """
    conflicts: set[tuple[int, int]] = set()
    for unit in UNITS:
        seen: dict[int, int] = {}
        for cell in unit:
            value = int(board[cell])
            if value == EMPTY:
                continue
            if value in seen:
                conflicts.add((min(seen[value], cell), max(seen[value], cell)))
            else:
                seen[value] = cell
    return sorted(conflicts)


def is_consistent(board: np.ndarray) -> bool:
    """True if the board breaks no constraint (it may still be incomplete)."""
    return not find_conflicts(board)


def is_solved(board: np.ndarray) -> bool:
    """True only if the board is both complete and consistent."""
    return is_complete(board) and is_consistent(board)


def clue_count(board: np.ndarray) -> int:
    """Number of filled cells. The crudest difficulty proxy there is."""
    return int((board != EMPTY).sum())


def to_grid(board: np.ndarray) -> np.ndarray:
    """Return a ``(9, 9)`` *view* of the flat board -- no copy is made."""
    return board.reshape(N, N)

"""Constraint propagation over candidate sets.

Every cell holds a *domain*: the set of digits it could still take. We store a
domain as a 9-bit integer, bit ``d - 1`` meaning "digit ``d`` is still possible".
Bitmasks make the inner loop branch-free and cheap:

    intersection   a & b
    removal        a & ~bit(d)
    "is singleton" mask.bit_count() == 1

Three inference rules live here, in increasing strength:

1. **Naked single** -- a cell with one candidate left must take it.
2. **Arc consistency (AC-3)** -- the textbook algorithm, run over the binary
   decomposition of the all-different constraints. On sudoku this turns out to
   be *exactly as strong as* naked singles, and Lesson 04 asks you to work out
   why. (Briefly: a binary ``!=`` arc can only prune when the other end is
   already a singleton.)
3. **Hidden single** -- if a digit has only one possible home left inside a
   unit, it goes there, even if that cell has several candidates. This reasons
   about the all-different constraint *as a whole*, so it is strictly stronger
   than arc consistency on the decomposition.

That gap between (2) and (3) is the whole reason "just run AC-3" does not solve
hard puzzles, and it is worth understanding before Stage 2 asks a neural network
to learn the same inferences.
"""

from __future__ import annotations

from .board import EMPTY
from .units import N, N_CELLS, PEERS, UNITS, UNITS_OF

#: All nine digits possible: 0b111111111.
FULL_MASK = (1 << N) - 1

Domains = list[int]


def bit(digit: int) -> int:
    """The single-bit mask for a digit 1..9."""
    return 1 << (digit - 1)


def mask_to_digits(mask: int) -> list[int]:
    """Expand a bitmask into the sorted list of digits it contains."""
    return [d for d in range(1, N + 1) if mask & bit(d)]


def only_digit(mask: int) -> int:
    """The digit in a singleton mask. Undefined for non-singletons."""
    return mask.bit_length()


def initial_domains(board) -> Domains | None:
    """Build starting domains from a board, pruning givens from their peers.

    Returns ``None`` if the board is already contradictory.
    """
    domains: Domains = [FULL_MASK] * N_CELLS
    for cell in range(N_CELLS):
        value = int(board[cell])
        if value == EMPTY:
            continue
        if not domains[cell] & bit(value):
            return None
        domains[cell] = bit(value)
        for peer in PEERS[cell]:
            domains[peer] &= ~bit(value)
            if domains[peer] == 0:
                return None
    return domains


def domains_to_board(domains: Domains, out) -> None:
    """Write every singleton domain back into ``out`` as a digit."""
    for cell in range(N_CELLS):
        mask = domains[cell]
        if mask.bit_count() == 1:
            out[cell] = only_digit(mask)


def naked_singles(domains: Domains) -> bool:
    """Propagate singleton domains to a fixpoint.

    Returns ``False`` on contradiction (some domain became empty).
    """
    queue = [c for c in range(N_CELLS) if domains[c].bit_count() == 1]
    while queue:
        cell = queue.pop()
        mask = domains[cell]
        if mask.bit_count() != 1:
            continue
        for peer in PEERS[cell]:
            if domains[peer] & mask:
                domains[peer] &= ~mask
                if domains[peer] == 0:
                    return False
                if domains[peer].bit_count() == 1:
                    queue.append(peer)
    return True


def hidden_singles(domains: Domains) -> bool:
    """Place digits that have exactly one possible cell within a unit.

    Returns ``False`` on contradiction (a digit with nowhere to go).
    """
    changed = True
    while changed:
        changed = False
        for unit in UNITS:
            for digit in range(1, N + 1):
                mask = bit(digit)
                homes = [cell for cell in unit if domains[cell] & mask]
                if not homes:
                    return False
                if len(homes) == 1:
                    cell = homes[0]
                    if domains[cell] != mask:
                        domains[cell] = mask
                        changed = True
                        if not naked_singles(domains):
                            return False
    return True


def revise(domains: Domains, xi: int, xj: int) -> bool:
    """AC-3's inner step: prune values of ``xi`` unsupported by ``xj``.

    For an all-different constraint the only unsupported value is ``xj``'s own
    value, and only when ``xj`` has just one candidate left.
    """
    if domains[xj].bit_count() != 1:
        return False
    if not domains[xi] & domains[xj]:
        return False
    domains[xi] &= ~domains[xj]
    return True


def ac3(domains: Domains) -> bool:
    """Textbook AC-3 over the binary decomposition of the sudoku constraints.

    Returns ``False`` if a domain is wiped out, ``True`` otherwise. Note that
    ``True`` does *not* mean solved -- see :func:`propagate`.
    """
    queue = [(xi, xj) for xj in range(N_CELLS) for xi in PEERS[xj]]
    while queue:
        xi, xj = queue.pop(0)
        if revise(domains, xi, xj):
            if domains[xi] == 0:
                return False
            queue.extend((xk, xi) for xk in PEERS[xi] if xk != xj)
    return True


def propagate(domains: Domains) -> bool:
    """Run naked singles and hidden singles together to a fixpoint.

    This is the propagator the search in :mod:`gridmind.solvers.backtracking`
    uses. Returns ``False`` on contradiction.
    """
    if not naked_singles(domains):
        return False
    return hidden_singles(domains)


def is_solved_domains(domains: Domains) -> bool:
    """True when every domain is a singleton."""
    return all(mask.bit_count() == 1 for mask in domains)


def unsolved_count(domains: Domains) -> int:
    """How many cells still have more than one candidate."""
    return sum(1 for mask in domains if mask.bit_count() > 1)

/** Board parsing, formatting and validation. Twin of `src/gridmind/board.py`. */

import { N, N_CELLS, UNITS } from "./units";

export const EMPTY = 0;

const BLANK_CHARS = new Set([".", "0", "_", "*"]);
const LAYOUT_CHARS = new Set(["|", "+", "-"]);

export type Board = Uint8Array;

export function fromString(text: string): Board {
  const digits: number[] = [];
  for (const ch of text) {
    if (/\s/.test(ch) || LAYOUT_CHARS.has(ch)) continue;
    if (BLANK_CHARS.has(ch)) digits.push(EMPTY);
    else if (ch >= "1" && ch <= "9") digits.push(Number(ch));
    else throw new Error(`unexpected character ${ch} in board string`);
  }
  if (digits.length !== N_CELLS) {
    throw new Error(`expected ${N_CELLS} cells, got ${digits.length}`);
  }
  return Uint8Array.from(digits);
}

export const toString_ = (board: Board): string => Array.from(board).join("");

export const isComplete = (board: Board): boolean =>
  !board.some((value) => value === EMPTY);

export function findConflicts(board: Board): Array<[number, number]> {
  const conflicts = new Set<string>();
  for (const unit of UNITS) {
    const seen = new Map<number, number>();
    for (const cell of unit) {
      const value = board[cell]!;
      if (value === EMPTY) continue;
      const previous = seen.get(value);
      if (previous !== undefined) {
        conflicts.add(`${Math.min(previous, cell)},${Math.max(previous, cell)}`);
      } else {
        seen.set(value, cell);
      }
    }
  }
  return [...conflicts].map((key) => {
    const [a, b] = key.split(",");
    return [Number(a), Number(b)] as [number, number];
  });
}

export const isConsistent = (board: Board): boolean =>
  findConflicts(board).length === 0;

export const isSolved = (board: Board): boolean =>
  isComplete(board) && isConsistent(board);

export const clueCount = (board: Board): number =>
  board.reduce((total, value) => total + (value === EMPTY ? 0 : 1), 0);

export function render(board: Board, blank = "."): string {
  const lines: string[] = [];
  for (let r = 0; r < N; r += 1) {
    if (r > 0 && r % 3 === 0) lines.push("------+-------+------");
    const cells: string[] = [];
    for (let c = 0; c < N; c += 1) {
      if (c > 0 && c % 3 === 0) cells.push("|");
      const value = board[r * N + c]!;
      cells.push(value === EMPTY ? blank : String(value));
    }
    lines.push(cells.join(" "));
  }
  return lines.join("\n");
}

/**
 * Propagation and search, ported from `src/gridmind/propagate.py` and
 * `src/gridmind/solvers/backtracking.py`.
 *
 * The one addition over the Python version is the **event log**. Every
 * inference and every branch can be recorded, which is what makes Lessons 46
 * and 47 possible: you replay the log to animate the solver's reasoning
 * instead of just showing the answer.
 */

import { EMPTY, type Board } from "./board";
import { N, N_CELLS, PEERS, UNITS } from "./units";

export const FULL_MASK = (1 << N) - 1;

export type Domains = Int16Array;

export const bit = (digit: number): number => 1 << (digit - 1);
export const popcount = (mask: number): number => {
  let count = 0;
  let m = mask;
  while (m) {
    m &= m - 1;
    count += 1;
  }
  return count;
};
export const onlyDigit = (mask: number): number => 32 - Math.clz32(mask);
export const maskToDigits = (mask: number): number[] => {
  const digits: number[] = [];
  for (let d = 1; d <= N; d += 1) if (mask & bit(d)) digits.push(d);
  return digits;
};

export type SolveEvent =
  | { kind: "given"; cell: number; digit: number }
  | { kind: "naked-single"; cell: number; digit: number }
  | { kind: "hidden-single"; cell: number; digit: number; unit: number }
  | { kind: "branch"; cell: number; digit: number; candidates: number[] }
  | { kind: "backtrack"; cell: number; digit: number }
  | { kind: "contradiction"; cell: number }
  | { kind: "solved" };

export interface SearchStats {
  /** When false, counters still update but no events are captured. */
  record: boolean;
  nodes: number;
  backtracks: number;
  propagations: number;
  events: SolveEvent[];
  ms: number;
}

const pushEvent = (stats: SearchStats | undefined, event: SolveEvent): void => {
  if (stats?.record) stats.events.push(event);
};

export const emptyStats = (record = false): SearchStats => ({
  record,
  nodes: 0,
  backtracks: 0,
  propagations: 0,
  events: [],
  ms: 0,
});

export function initialDomains(
  board: Board,
  stats?: SearchStats,
): Domains | null {
  const domains = new Int16Array(N_CELLS).fill(FULL_MASK);
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    const value = board[cell]!;
    if (value === EMPTY) continue;
    if (!(domains[cell]! & bit(value))) return null;
    domains[cell] = bit(value);
    pushEvent(stats, { kind: "given", cell, digit: value });
    for (const peer of PEERS[cell]!) {
      domains[peer]! &= ~bit(value);
      if (domains[peer] === 0) {
        pushEvent(stats, { kind: "contradiction", cell: peer });
        return null;
      }
    }
  }
  return domains;
}

export function nakedSingles(domains: Domains, stats?: SearchStats): boolean {
  const queue: number[] = [];
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    if (popcount(domains[cell]!) === 1) queue.push(cell);
  }
  while (queue.length > 0) {
    const cell = queue.pop()!;
    const mask = domains[cell]!;
    if (popcount(mask) !== 1) continue;
    for (const peer of PEERS[cell]!) {
      if (domains[peer]! & mask) {
        domains[peer]! &= ~mask;
        if (domains[peer] === 0) {
          pushEvent(stats, { kind: "contradiction", cell: peer });
          return false;
        }
        if (popcount(domains[peer]!) === 1) {
          pushEvent(stats, {
            kind: "naked-single",
            cell: peer,
            digit: onlyDigit(domains[peer]!),
          });
          queue.push(peer);
        }
      }
    }
  }
  return true;
}

export function hiddenSingles(domains: Domains, stats?: SearchStats): boolean {
  let changed = true;
  while (changed) {
    changed = false;
    for (let u = 0; u < UNITS.length; u += 1) {
      const unit = UNITS[u]!;
      for (let digit = 1; digit <= N; digit += 1) {
        const mask = bit(digit);
        const homes = unit.filter((cell) => domains[cell]! & mask);
        if (homes.length === 0) return false;
        if (homes.length === 1) {
          const cell = homes[0]!;
          if (domains[cell] !== mask) {
            domains[cell] = mask;
            changed = true;
            pushEvent(stats, {
              kind: "hidden-single",
              cell,
              digit,
              unit: u,
            });
            if (!nakedSingles(domains, stats)) return false;
          }
        }
      }
    }
  }
  return true;
}

export function propagate(domains: Domains, stats?: SearchStats): boolean {
  if (stats) stats.propagations += 1;
  if (!nakedSingles(domains, stats)) return false;
  return hiddenSingles(domains, stats);
}

/** MRV: branch on the cell with the fewest candidates. -1 when all decided. */
export function mrv(domains: Domains): number {
  let bestCell = -1;
  let bestSize = N + 1;
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    const size = popcount(domains[cell]!);
    if (size > 1 && size < bestSize) {
      bestSize = size;
      bestCell = cell;
      if (size === 2) break;
    }
  }
  return bestCell;
}

function search(
  domains: Domains,
  stats: SearchStats,
  out: { result: Domains | null },
): boolean {
  const cell = mrv(domains);
  if (cell < 0) {
    out.result = domains.slice();
    pushEvent(stats, { kind: "solved" });
    return true;
  }

  stats.nodes += 1;
  const candidates = maskToDigits(domains[cell]!);
  for (const digit of candidates) {
    pushEvent(stats, { kind: "branch", cell, digit, candidates });
    const branch = domains.slice();
    branch[cell] = bit(digit);
    if (propagate(branch, stats)) {
      if (search(branch, stats, out)) return true;
    }
    stats.backtracks += 1;
    pushEvent(stats, { kind: "backtrack", cell, digit });
  }
  return false;
}

export interface SolveResult {
  solution: Board | null;
  stats: SearchStats;
}

export function solve(board: Board, record = false): SolveResult {
  const stats = emptyStats(record);
  const started = performance.now();

  const domains = initialDomains(board, stats);
  if (domains === null) {
    stats.ms = performance.now() - started;
    return { solution: null, stats };
  }
  if (!propagate(domains, stats)) {
    stats.ms = performance.now() - started;
    return { solution: null, stats };
  }

  const out: { result: Domains | null } = { result: null };
  search(domains, stats, out);
  stats.ms = performance.now() - started;

  if (out.result === null) return { solution: null, stats };
  const solution = new Uint8Array(N_CELLS);
  for (let cell = 0; cell < N_CELLS; cell += 1) {
    solution[cell] = onlyDigit(out.result[cell]!);
  }
  return { solution, stats };
}

/** Candidate sets after propagation only — what Lesson 47 renders. */
export function candidatesAfterPropagation(board: Board): Domains | null {
  const domains = initialDomains(board);
  if (domains === null) return null;
  return propagate(domains) ? domains : null;
}

/**
 * Grid structure: units, peers, and the constraint graph.
 *
 * This is the TypeScript twin of `src/gridmind/units.py`. Keeping the two in
 * step is deliberate — Lesson 45 asks you to port the solver and check that
 * both implementations agree node-for-node on the same puzzles.
 */

export const N = 9;
export const BOX = 3;
export const N_CELLS = N * N;

export const rcToIndex = (row: number, col: number): number => row * N + col;
export const indexToRc = (index: number): [number, number] => [
  Math.floor(index / N),
  index % N,
];

export const boxOf = (index: number): number => {
  const [row, col] = indexToRc(index);
  return Math.floor(row / BOX) * BOX + Math.floor(col / BOX);
};

const buildRows = (): number[][] =>
  Array.from({ length: N }, (_, r) =>
    Array.from({ length: N }, (_, c) => rcToIndex(r, c)),
  );

const buildCols = (): number[][] =>
  Array.from({ length: N }, (_, c) =>
    Array.from({ length: N }, (_, r) => rcToIndex(r, c)),
  );

const buildBoxes = (): number[][] => {
  const boxes: number[][] = Array.from({ length: N }, () => []);
  for (let cell = 0; cell < N_CELLS; cell += 1) boxes[boxOf(cell)]!.push(cell);
  return boxes;
};

export const ROWS = buildRows();
export const COLS = buildCols();
export const BOXES = buildBoxes();

/** All 27 units: nine rows, nine columns, nine boxes. */
export const UNITS: number[][] = [...ROWS, ...COLS, ...BOXES];

/** The three units each cell belongs to. */
export const UNITS_OF: number[][][] = Array.from({ length: N_CELLS }, (_, cell) =>
  UNITS.filter((unit) => unit.includes(cell)),
);

/** The 20 cells that constrain each cell. */
export const PEERS: number[][] = Array.from({ length: N_CELLS }, (_, cell) => {
  const peers = new Set<number>();
  for (const unit of UNITS_OF[cell]!) {
    for (const other of unit) if (other !== cell) peers.add(other);
  }
  return [...peers].sort((a, b) => a - b);
});

/** Undirected constraint graph, each edge once with a < b. 810 of them. */
export const EDGES: Array<[number, number]> = (() => {
  const edges: Array<[number, number]> = [];
  for (let a = 0; a < N_CELLS; a += 1) {
    for (const b of PEERS[a]!) if (a < b) edges.push([a, b]);
  }
  return edges;
})();

/**
 * Wiring for the browser app.
 *
 * Everything runs client-side: the puzzle never leaves the page, and there is
 * no server to talk to. That is the same property that makes the Stage 7
 * lessons deployable as a static site.
 */

import {
  clueCount,
  fromString,
  isSolved,
  toString_,
  type Board,
} from "./core/board";
import { candidatesAfterPropagation, solve, type SolveEvent } from "./core/solve";
import { N_CELLS } from "./core/units";
import { createGrid } from "./ui/grid";
import { mountLessons, type LessonsHandle } from "./ui/lessons";
import {
  loadBundle,
  mountCode,
  mountDocs,
  type CodeHandle,
  type DocsHandle,
} from "./ui/docs";
import { setNavigationHandler, type Target, type ViewName } from "./ui/navigation";

interface LibraryPuzzle {
  id: string;
  puzzle: string;
  solution: string;
  clues: number;
  nodes: number;
  band: string;
  label: string;
}

/** Shown until the library loads, and if it fails to load at all. */
const FALLBACK: LibraryPuzzle = {
  id: "fallback",
  puzzle:
    "000000000302540000050301070000000004409006005023054790" +
    "000000050700810000080060009",
  solution:
    "148697523372548961956321478567983214419276385823154796" +
    "691432857735819642284765139",
  clues: 26,
  nodes: 3,
  band: "Light search",
  label: "Reference: hard",
};

const el = <T extends HTMLElement>(id: string): T => {
  const node = document.getElementById(id);
  if (node === null) throw new Error(`missing element #${id}`);
  return node as T;
};

const gridEl = el<HTMLDivElement>("grid");
const input = el<HTMLTextAreaElement>("puzzle-input");
const statsEl = el<HTMLPreElement>("stats");
const showCandidates = el<HTMLInputElement>("show-candidates");
const picker = el<HTMLSelectElement>("puzzle-select");
const metaEl = el<HTMLParagraphElement>("puzzle-meta");

let library: LibraryPuzzle[] = [FALLBACK];
let currentIndex = 0;

const grid = createGrid(gridEl);
let animation: number | null = null;

function stopAnimation(): void {
  if (animation !== null) {
    window.clearTimeout(animation);
    animation = null;
  }
}

function loadBoard(board: Board): void {
  stopAnimation();
  grid.setBoard(board);
  grid.setGivens(Array.from(board, (value) => value !== 0));
  grid.setBranchCells(new Set());
  grid.setCandidates(null);
  input.value = toString_(board);
  refreshCandidates();
  statsEl.textContent = `${clueCount(board)} clues loaded.`;
}

function refreshCandidates(): void {
  if (!showCandidates.checked) {
    grid.setCandidates(null);
    return;
  }
  grid.setCandidates(candidatesAfterPropagation(grid.getBoard()));
}

function runSolve(): void {
  stopAnimation();
  const board = grid.getBoard();
  const { solution, stats } = solve(board);
  if (solution === null) {
    statsEl.textContent = "No solution.\n\nThe puzzle is over-constrained.";
    return;
  }
  grid.setBoard(solution);
  grid.setCandidates(null);
  statsEl.textContent = [
    `solved       ${isSolved(solution)}`,
    `nodes        ${stats.nodes}`,
    `backtracks   ${stats.backtracks}`,
    `propagations ${stats.propagations}`,
    `time         ${stats.ms.toFixed(2)} ms`,
    "",
    stats.nodes === 0
      ? "Zero nodes: constraint propagation alone was enough."
      : "Nonzero nodes: the solver had to guess and backtrack.",
  ].join("\n");
}

function runAnimation(): void {
  stopAnimation();
  const start = grid.getBoard();
  const { solution, stats } = solve(start, true);
  if (solution === null) {
    statsEl.textContent = "No solution to animate.";
    return;
  }

  const board = start.slice();
  const branchCells = new Set<number>();
  grid.setBoard(board);
  grid.setCandidates(null);

  const events = stats.events;
  let index = 0;

  const step = (): void => {
    // Skip ahead over the givens; they are already on the board.
    let event: SolveEvent | undefined;
    while (index < events.length) {
      event = events[index];
      index += 1;
      if (event && event.kind !== "given") break;
      event = undefined;
    }
    if (event === undefined) {
      grid.setActive(null);
      statsEl.textContent += "\n\nReplay finished.";
      animation = null;
      return;
    }

    switch (event.kind) {
      case "naked-single":
      case "hidden-single":
        board[event.cell] = event.digit;
        grid.setActive(event.cell);
        break;
      case "branch":
        board[event.cell] = event.digit;
        branchCells.add(event.cell);
        grid.setActive(event.cell);
        break;
      case "backtrack":
        board[event.cell] = 0;
        branchCells.delete(event.cell);
        grid.setActive(event.cell);
        break;
      case "contradiction":
        grid.setActive(event.cell);
        break;
      case "solved":
        grid.setActive(null);
        break;
    }

    grid.setBoard(board);
    grid.setBranchCells(branchCells);
    statsEl.textContent = [
      `replaying    ${index}/${events.length}`,
      `last event   ${event.kind}`,
      "",
      "blue = inferred    orange = guessed",
    ].join("\n");
    animation = window.setTimeout(step, 40);
  };

  step();
}

// --- puzzle library ---------------------------------------------------------

function describe(entry: LibraryPuzzle): string {
  const name = entry.label !== "" ? entry.label : entry.id;
  return `${name} — ${entry.clues} clues, ${entry.nodes} nodes`;
}

function renderMeta(entry: LibraryPuzzle): void {
  const searchy = entry.nodes > 0;
  metaEl.innerHTML =
    `<span class="tag${searchy ? " search" : ""}">${entry.band}</span>` +
    `<span class="tag">${entry.clues} clues</span>` +
    `<span class="tag">${entry.nodes} nodes</span>`;
  metaEl.title = searchy
    ? "This puzzle needs guessing: propagation alone does not finish it."
    : "Constraint propagation alone solves this one — no search required.";
}

function selectIndex(index: number, { announce = true } = {}): void {
  if (library.length === 0) return;
  currentIndex = ((index % library.length) + library.length) % library.length;
  const entry = library[currentIndex]!;
  picker.value = entry.id;
  renderMeta(entry);
  loadBoard(fromString(entry.puzzle));
  if (announce) {
    statsEl.textContent =
      `${describe(entry)}\n\nPress Solve, or Animate to watch it think.`;
  }
}

function populatePicker(): void {
  picker.replaceChildren();
  for (const band of [...new Set(library.map((p) => p.band))]) {
    const group = document.createElement("optgroup");
    group.label = band;
    for (const entry of library.filter((p) => p.band === band)) {
      const option = document.createElement("option");
      option.value = entry.id;
      option.textContent = describe(entry);
      group.append(option);
    }
    picker.append(group);
  }
}

async function loadLibrary(): Promise<void> {
  const puzzles = await loadBundle<LibraryPuzzle[]>("puzzles.json");
  if (puzzles !== null && puzzles.length > 0) library = puzzles;
  populatePicker();

  // Open on a real puzzle rather than an empty grid, and make it obvious
  // which one is selected.
  const preferred = library.findIndex((p) => p.label === "Reference: hard");
  selectIndex(preferred >= 0 ? preferred : 0);
}

picker.addEventListener("change", () => {
  const index = library.findIndex((p) => p.id === picker.value);
  if (index >= 0) selectIndex(index);
});

el("prev").addEventListener("click", () => selectIndex(currentIndex - 1));
el("next").addEventListener("click", () => selectIndex(currentIndex + 1));
el("random").addEventListener("click", () => {
  if (library.length < 2) return selectIndex(0);
  let next = currentIndex;
  while (next === currentIndex) next = Math.floor(Math.random() * library.length);
  selectIndex(next);
});
el("reset").addEventListener("click", () => selectIndex(currentIndex));
el("empty").addEventListener("click", () => {
  stopAnimation();
  loadBoard(new Uint8Array(N_CELLS));
  metaEl.innerHTML = '<span class="tag">empty grid</span>';
  statsEl.textContent = "Empty grid. Solve it to generate a complete board.";
});

el("load").addEventListener("click", () => {
  try {
    loadBoard(fromString(input.value));
    metaEl.innerHTML = '<span class="tag">custom</span>';
  } catch (error) {
    statsEl.textContent = `Could not parse:\n${(error as Error).message}`;
  }
});

el("solve").addEventListener("click", runSolve);
el("animate").addEventListener("click", runAnimation);

showCandidates.addEventListener("change", refreshCandidates);
grid.onChange(refreshCandidates);

void loadLibrary();

// --- view switching ---------------------------------------------------------

const VIEWS: ViewName[] = ["solver", "lessons", "docs", "code"];

const handles: {
  lessons?: LessonsHandle;
  docs?: DocsHandle;
  code?: CodeHandle;
} = {};

/** Each browser view is mounted lazily, the first time it is opened. */
const MOUNTERS: Partial<Record<ViewName, () => Promise<void>>> = {
  lessons: async () => {
    handles.lessons = await mountLessons(el("lesson-list"), el("lesson-content"));
  },
  docs: async () => {
    handles.docs = await mountDocs(el("docs-list"), el("docs-content"));
  },
  code: async () => {
    handles.code = await mountCode(el("code-list"), el("code-content"));
  },
};

const mounted = new Set<ViewName>();

async function showView(view: ViewName): Promise<void> {
  for (const name of VIEWS) {
    el(`${name}-view`).classList.toggle("hidden", name !== view);
    el(`view-${name}`).classList.toggle("active", name === view);
  }
  if (location.hash !== `#${view}`) location.hash = view;

  if (!mounted.has(view)) {
    mounted.add(view);
    await MOUNTERS[view]?.();
  }
}

for (const name of VIEWS) {
  el(`view-${name}`).addEventListener("click", () => void showView(name));
}

/**
 * Links inside rendered markdown route here instead of navigating the page.
 * Without this, clicking `NOTES.md` would leave the SPA at a bogus path and
 * every relative fetch would break — which is exactly the "Could not load
 * docs.json" failure this replaced.
 */
setNavigationHandler((target: Target) => {
  void showView(target.view).then(() => {
    if (target.ref === undefined) return;
    if (target.view === "docs") handles.docs?.show(target.ref);
    if (target.view === "lessons") handles.lessons?.show(target.ref);
    if (target.view === "code") handles.code?.show(target.ref);
  });
});

const initial = location.hash.replace("#", "") as ViewName;
void showView(VIEWS.includes(initial) ? initial : "solver");

/**
 * Docs and code browsers.
 *
 * Both read JSON bundles written by `tools/scaffold_lessons.py`, so the whole
 * repo — every markdown file and every source file — is readable in the app
 * with no network and no server beyond the static host. That matters because
 * this is the only documentation you have when you are offline.
 */

import { marked } from "marked";

import { createEditor } from "./editor";
import { attachLinkHandler } from "./navigation";

interface Doc {
  name: string;
  label: string;
  text: string;
}

interface CodeFile {
  path: string;
  group: string;
  lines: number;
  text: string;
}

export interface DocsHandle {
  show(name: string): void;
}

export interface CodeHandle {
  show(path: string): void;
}

/**
 * Fetch a bundle from `public/`.
 *
 * Tries the relative path first (correct for a GitHub Pages subpath) and falls
 * back to an absolute one, so a stray deep URL cannot leave the app unable to
 * load its own content.
 */
export async function loadBundle<T>(name: string): Promise<T | null> {
  for (const url of [`./${name}`, `/${name}`]) {
    try {
      const response = await fetch(url);
      if (!response.ok) continue;
      return (await response.json()) as T;
    } catch {
      // try the next candidate
    }
  }
  return null;
}

function missing(contentEl: HTMLElement, name: string): void {
  contentEl.innerHTML =
    `<p>Could not load <code>${name}</code>. Regenerate it with ` +
    "<code>python tools/scaffold_lessons.py</code>, then reload.</p>";
}

export async function mountDocs(
  listEl: HTMLElement,
  contentEl: HTMLElement,
): Promise<DocsHandle> {
  const docs = await loadBundle<Doc[]>("docs.json");
  if (docs === null || docs.length === 0) {
    missing(contentEl, "docs.json");
    return { show: () => {} };
  }

  let current = docs[0]!;

  function renderList(): void {
    listEl.replaceChildren();
    const list = document.createElement("ul");
    list.className = "lesson-list";
    for (const doc of docs!) {
      const item = document.createElement("li");
      const button = document.createElement("button");
      button.type = "button";
      button.className = doc.name === current.name ? "lesson active" : "lesson";
      button.innerHTML =
        `<span class="lesson-title">${doc.label}</span>` +
        `<span class="kind">${doc.name}</span>`;
      button.addEventListener("click", () => {
        current = doc;
        renderList();
        renderContent();
      });
      item.append(button);
      list.append(item);
    }
    listEl.append(list);
  }

  function renderContent(): void {
    contentEl.replaceChildren();
    const article = document.createElement("article");
    article.className = "markdown";
    article.innerHTML = marked.parse(current.text, { async: false }) as string;
    contentEl.append(article);
    // Repo-root-relative links, since these docs live at the top level.
    attachLinkHandler(article, "");
  }

  renderList();
  renderContent();

  return {
    show(name) {
      const found = docs.find((doc) => doc.name === name);
      if (found === undefined) return;
      current = found;
      renderList();
      renderContent();
      contentEl.scrollIntoView({ behavior: "smooth", block: "start" });
    },
  };
}

export async function mountCode(
  listEl: HTMLElement,
  contentEl: HTMLElement,
): Promise<CodeHandle> {
  const files = await loadBundle<CodeFile[]>("code.json");
  if (files === null || files.length === 0) {
    missing(contentEl, "code.json");
    return { show: () => {} };
  }

  const byPath = new Map(files.map((file) => [file.path, file]));
  const open: string[] = [];
  let current = files[0]!.path;
  let filter = "";

  // --- editor pane, built once ---------------------------------------------

  contentEl.replaceChildren();

  const tabBar = document.createElement("div");
  tabBar.className = "editor-tabs";

  const status = document.createElement("div");
  status.className = "editor-status";

  const host = document.createElement("div");
  host.className = "editor-host";

  contentEl.append(tabBar, host, status);
  const editor = createEditor(host);

  function openFile(path: string): void {
    const file = byPath.get(path);
    if (file === undefined) {
      status.textContent = `${path} is not in the bundle — regenerate with tools/scaffold_lessons.py`;
      return;
    }
    current = path;
    if (!open.includes(path)) open.push(path);
    if (open.length > 8) open.shift();
    editor.show(file.path, file.text);
    status.textContent =
      `${file.path}  ·  ${file.lines} lines  ·  ${file.group}` +
      "  ·  read-only (Cmd-F to search)";
    renderTabs();
    renderList();
  }

  function renderTabs(): void {
    tabBar.replaceChildren();
    for (const path of open) {
      const tab = document.createElement("div");
      tab.className = path === current ? "editor-tab active" : "editor-tab";

      const label = document.createElement("button");
      label.type = "button";
      label.className = "editor-tab-label";
      label.textContent = path.split("/").pop() ?? path;
      label.title = path;
      label.addEventListener("click", () => openFile(path));

      const close = document.createElement("button");
      close.type = "button";
      close.className = "editor-tab-close";
      close.textContent = "×";
      close.setAttribute("aria-label", `Close ${path}`);
      close.addEventListener("click", (event) => {
        event.stopPropagation();
        const index = open.indexOf(path);
        open.splice(index, 1);
        if (current === path && open.length > 0) {
          openFile(open[Math.max(0, index - 1)]!);
        } else {
          renderTabs();
        }
      });

      tab.append(label, close);
      tabBar.append(tab);
    }
  }

  // --- file tree ------------------------------------------------------------

  function renderList(): void {
    listEl.replaceChildren();

    const search = document.createElement("input");
    search.type = "search";
    search.placeholder = `Filter ${files!.length} files…`;
    search.className = "code-filter";
    search.value = filter;
    search.addEventListener("input", () => {
      filter = search.value.toLowerCase();
      renderList();
      const box = listEl.querySelector<HTMLInputElement>(".code-filter");
      box?.focus();
      box?.setSelectionRange(filter.length, filter.length);
    });
    listEl.append(search);

    const visible = files!.filter((f) => f.path.toLowerCase().includes(filter));
    if (visible.length === 0) {
      const empty = document.createElement("p");
      empty.className = "hint";
      empty.textContent = "No files match.";
      listEl.append(empty);
      return;
    }

    for (const group of [...new Set(visible.map((f) => f.group))]) {
      const heading = document.createElement("h3");
      heading.className = "stage-heading";
      heading.textContent = group;
      listEl.append(heading);

      const list = document.createElement("ul");
      list.className = "lesson-list";
      for (const file of visible.filter((f) => f.group === group)) {
        const item = document.createElement("li");
        const button = document.createElement("button");
        button.type = "button";
        button.className = file.path === current ? "lesson active" : "lesson";
        button.innerHTML =
          `<span class="lesson-title code-path">${file.path}</span>` +
          `<span class="kind">${file.lines}</span>`;
        button.addEventListener("click", () => openFile(file.path));
        item.append(button);
        list.append(item);
      }
      listEl.append(list);
    }
  }

  openFile(current);

  return {
    show(path) {
      openFile(path);
      contentEl.scrollIntoView({ behavior: "smooth", block: "start" });
    },
  };
}

/**
 * A read-only CodeMirror 6 editor, used by the Code tab.
 *
 * Read-only deliberately: this is a *viewer* for the repo, not a second place
 * to edit it. Edit in VS Code, then re-run `tools/scaffold_lessons.py` to
 * refresh the bundle the browser reads.
 *
 * You get real syntax highlighting, line numbers, code folding, bracket
 * matching, and Cmd-F search within the file — the parts of an IDE that
 * actually help you read unfamiliar code.
 */

import { defaultKeymap, history, historyKeymap } from "@codemirror/commands";
import { css } from "@codemirror/lang-css";
import { html } from "@codemirror/lang-html";
import { javascript } from "@codemirror/lang-javascript";
import { json } from "@codemirror/lang-json";
import { python } from "@codemirror/lang-python";
import {
  bracketMatching,
  foldGutter,
  foldKeymap,
  indentOnInput,
  syntaxHighlighting,
  defaultHighlightStyle,
} from "@codemirror/language";
import { highlightSelectionMatches, search, searchKeymap } from "@codemirror/search";
import { EditorState, type Extension } from "@codemirror/state";
import { oneDark } from "@codemirror/theme-one-dark";
import {
  EditorView,
  drawSelection,
  highlightActiveLine,
  highlightActiveLineGutter,
  keymap,
  lineNumbers,
} from "@codemirror/view";

/** Pick a language mode from the file extension. */
function languageFor(path: string): Extension[] {
  if (path.endsWith(".py")) return [python()];
  if (path.endsWith(".ts") || path.endsWith(".js")) {
    return [javascript({ typescript: path.endsWith(".ts") })];
  }
  if (path.endsWith(".css")) return [css()];
  if (path.endsWith(".html")) return [html()];
  if (path.endsWith(".json")) return [json()];
  return [];
}

const prefersDark = (): boolean =>
  window.matchMedia?.("(prefers-color-scheme: dark)").matches ?? false;

const baseTheme = EditorView.theme({
  "&": { height: "100%", fontSize: "0.78rem" },
  ".cm-scroller": {
    fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
    lineHeight: "1.6",
  },
  ".cm-gutters": { userSelect: "none" },
});

export interface CodeEditor {
  /** Swap the displayed file without tearing down the view. */
  show(path: string, text: string): void;
  /** Scroll to a 1-indexed line and put the cursor on it. */
  goToLine(line: number): void;
  destroy(): void;
}

export function createEditor(parent: HTMLElement): CodeEditor {
  let currentPath = "";

  const extensions = (path: string): Extension[] => [
    lineNumbers(),
    highlightActiveLineGutter(),
    highlightActiveLine(),
    foldGutter(),
    drawSelection(),
    indentOnInput(),
    bracketMatching(),
    history(),
    search({ top: true }),
    highlightSelectionMatches(),
    syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
    keymap.of([...defaultKeymap, ...searchKeymap, ...historyKeymap, ...foldKeymap]),
    EditorState.readOnly.of(true),
    EditorView.editable.of(false),
    EditorView.lineWrapping,
    baseTheme,
    ...(prefersDark() ? [oneDark] : []),
    ...languageFor(path),
  ];

  const view = new EditorView({
    parent,
    state: EditorState.create({ doc: "", extensions: extensions("") }),
  });

  return {
    show(path, text) {
      // Language support is a static extension, so switching file type means
      // rebuilding state rather than dispatching a change.
      if (path !== currentPath) {
        currentPath = path;
        view.setState(EditorState.create({ doc: text, extensions: extensions(path) }));
      } else {
        view.dispatch({
          changes: { from: 0, to: view.state.doc.length, insert: text },
        });
      }
      view.scrollDOM.scrollTo({ top: 0 });
    },
    goToLine(line) {
      const total = view.state.doc.lines;
      const target = Math.min(Math.max(line, 1), total);
      const pos = view.state.doc.line(target).from;
      view.dispatch({
        selection: { anchor: pos },
        effects: EditorView.scrollIntoView(pos, { y: "center" }),
      });
      view.focus();
    },
    destroy() {
      view.destroy();
    },
  };
}

/** Grid rendering and keyboard editing. Lesson 43 and 44 live here. */

import { EMPTY, findConflicts, type Board } from "../core/board";
import { N_CELLS } from "../core/units";
import { maskToDigits, popcount, type Domains } from "../core/solve";

export interface GridView {
  /** Redraw from the current board. */
  render(): void;
  /** Replace the board and redraw. */
  setBoard(board: Board): void;
  getBoard(): Board;
  /** Cells that were given, so rendering can distinguish them from deductions. */
  setGivens(givens: boolean[]): void;
  /** Optional candidate overlay, or null to hide it. */
  setCandidates(domains: Domains | null): void;
  /** Highlight a single cell, e.g. during animation. */
  setActive(cell: number | null): void;
  /** Mark cells filled by search rather than inference. */
  setBranchCells(cells: Set<number>): void;
  onChange(handler: () => void): void;
}

export function createGrid(container: HTMLElement): GridView {
  let board: Board = new Uint8Array(N_CELLS);
  let givens: boolean[] = new Array(N_CELLS).fill(false);
  let candidates: Domains | null = null;
  let selected = 0;
  let active: number | null = null;
  let branchCells = new Set<number>();
  let changeHandler: () => void = () => {};

  const cells: HTMLDivElement[] = [];
  container.replaceChildren();
  for (let index = 0; index < N_CELLS; index += 1) {
    const cell = document.createElement("div");
    cell.className = "cell";
    cell.setAttribute("role", "gridcell");
    cell.tabIndex = index === 0 ? 0 : -1;
    cell.addEventListener("click", () => {
      selected = index;
      render();
      cell.focus();
    });
    container.append(cell);
    cells.push(cell);
  }

  container.addEventListener("keydown", (event: KeyboardEvent) => {
    const key = event.key;
    if (key >= "1" && key <= "9") {
      board[selected] = Number(key);
      candidates = null;
      changeHandler();
      render();
    } else if (key === "Backspace" || key === "Delete" || key === "0") {
      board[selected] = EMPTY;
      candidates = null;
      changeHandler();
      render();
    } else if (key.startsWith("Arrow")) {
      const delta =
        key === "ArrowLeft" ? -1 : key === "ArrowRight" ? 1 : key === "ArrowUp" ? -9 : 9;
      const next = selected + delta;
      if (next >= 0 && next < N_CELLS) {
        selected = next;
        cells[selected]!.focus();
        render();
      }
    } else {
      return;
    }
    event.preventDefault();
  });

  function render(): void {
    const conflicts = new Set(findConflicts(board).flat());
    for (let index = 0; index < N_CELLS; index += 1) {
      const element = cells[index]!;
      const value = board[index]!;
      element.className = "cell";
      element.replaceChildren();

      if (value !== EMPTY) {
        element.textContent = String(value);
        if (givens[index]) element.classList.add("given");
        else if (branchCells.has(index)) element.classList.add("branch");
        else element.classList.add("derived");
      } else if (candidates !== null) {
        const mask = candidates[index]!;
        if (popcount(mask) > 1) {
          const box = document.createElement("div");
          box.className = "candidates";
          const present = new Set(maskToDigits(mask));
          for (let digit = 1; digit <= 9; digit += 1) {
            const slot = document.createElement("span");
            slot.textContent = present.has(digit) ? String(digit) : "";
            box.append(slot);
          }
          element.append(box);
        }
      }

      if (index === selected) element.classList.add("selected");
      if (index === active) element.classList.add("active");
      if (conflicts.has(index)) element.classList.add("conflict");
    }
  }

  render();

  return {
    render,
    setBoard(next) {
      board = next.slice();
      render();
    },
    getBoard: () => board.slice(),
    setGivens(next) {
      givens = next;
      render();
    },
    setCandidates(next) {
      candidates = next;
      render();
    },
    setActive(cell) {
      active = cell;
      render();
    },
    setBranchCells(next) {
      branchCells = next;
      render();
    },
    onChange(handler) {
      changeHandler = handler;
    },
  };
}

/**
 * The lesson browser.
 *
 * `web/public/lessons.json` is regenerated by `tools/scaffold_lessons.py` and
 * carries every lesson's README and THEORY markdown inline, so browsing works
 * offline with no server beyond the static file host.
 */

import { marked } from "marked";

import { loadBundle } from "./docs";
import { attachLinkHandler } from "./navigation";

interface Lesson {
  n: number;
  slug: string;
  stage: number;
  stageName: string;
  title: string;
  kind: string;
  objective: string;
  readme: string;
  theory: string;
}

interface Stage {
  stage: number;
  name: string;
  blurb: string;
}

interface LessonIndex {
  stages: Stage[];
  lessons: Lesson[];
}

const KIND_CLASS: Record<string, string> = {
  ML: "kind-ml",
  "Classical AI": "kind-ai",
  Engineering: "kind-eng",
  "Computer Vision": "kind-cv",
  Frontend: "kind-web",
};

export interface LessonsHandle {
  /** Select a lesson by number, zero-padded or not. */
  show(ref: string): void;
}

export async function mountLessons(
  listEl: HTMLElement,
  contentEl: HTMLElement,
): Promise<LessonsHandle> {
  const loaded = await loadBundle<LessonIndex>("lessons.json");
  if (loaded === null || loaded.lessons.length === 0) {
    contentEl.innerHTML =
      "<p>Could not load <code>lessons.json</code>. Regenerate it with " +
      "<code>python tools/scaffold_lessons.py</code>, then reload.</p>";
    return { show: () => {} };
  }
  // Bound to a non-nullable const: the closures below outlive the guard, and
  // TypeScript does not carry the narrowing into them.
  const index: LessonIndex = loaded;

  let currentTab: "readme" | "theory" = "readme";
  let current: Lesson = index.lessons[0]!;

  const counts = new Map<string, number>();
  for (const lesson of index.lessons) {
    counts.set(lesson.kind, (counts.get(lesson.kind) ?? 0) + 1);
  }

  function renderList(): void {
    listEl.replaceChildren();

    const summary = document.createElement("div");
    summary.className = "kind-summary";
    for (const [kind, count] of [...counts].sort((a, b) => b[1] - a[1])) {
      const chip = document.createElement("span");
      chip.className = `kind ${KIND_CLASS[kind] ?? ""}`;
      chip.textContent = `${kind} ${count}`;
      summary.append(chip);
    }
    listEl.append(summary);

    for (const stage of index.stages) {
      const lessons = index.lessons.filter((l) => l.stage === stage.stage);
      if (lessons.length === 0) continue;

      const heading = document.createElement("h3");
      heading.className = "stage-heading";
      heading.textContent = `Stage ${stage.stage} — ${stage.name}`;
      listEl.append(heading);

      const list = document.createElement("ul");
      list.className = "lesson-list";
      for (const lesson of lessons) {
        const item = document.createElement("li");
        const button = document.createElement("button");
        button.type = "button";
        button.className = lesson.n === current.n ? "lesson active" : "lesson";
        button.innerHTML =
          `<span class="num">${String(lesson.n).padStart(2, "0")}</span>` +
          `<span class="lesson-title">${lesson.title}</span>` +
          `<span class="kind ${KIND_CLASS[lesson.kind] ?? ""}">${lesson.kind}</span>`;
        button.addEventListener("click", () => {
          current = lesson;
          currentTab = "readme";
          renderList();
          renderContent();
          contentEl.scrollIntoView({ behavior: "smooth", block: "start" });
        });
        item.append(button);
        list.append(item);
      }
      listEl.append(list);
    }
  }

  function renderContent(): void {
    contentEl.replaceChildren();

    const tabs = document.createElement("div");
    tabs.className = "tabs";
    for (const [key, label] of [
      ["readme", "Tasks"],
      ["theory", "Theory"],
    ] as const) {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = label;
      button.className = currentTab === key ? "tab active" : "tab";
      button.addEventListener("click", () => {
        currentTab = key;
        renderContent();
      });
      tabs.append(button);
    }
    contentEl.append(tabs);

    const runLine = document.createElement("pre");
    runLine.className = "runline";
    runLine.textContent =
      `.venv/bin/python lessons/${String(current.n).padStart(2, "0")}_` +
      `${current.slug}/run.py`;
    contentEl.append(runLine);

    const article = document.createElement("article");
    article.className = "markdown";
    const source = currentTab === "readme" ? current.readme : current.theory;
    article.innerHTML = marked.parse(source || "_Nothing written yet._", {
      async: false,
    }) as string;
    contentEl.append(article);
    // Lesson markdown links are relative to the lesson's own folder, so
    // `../../src/gridmind/board.py` has to resolve from there.
    attachLinkHandler(
      article,
      `lessons/${String(current.n).padStart(2, "0")}_${current.slug}/`,
    );
  }

  renderList();
  renderContent();

  return {
    show(ref) {
      const wanted = Number(ref);
      const found = index.lessons.find((lesson) => lesson.n === wanted);
      if (found === undefined) return;
      current = found;
      currentTab = "readme";
      renderList();
      renderContent();
      contentEl.scrollIntoView({ behavior: "smooth", block: "start" });
    },
  };
}

/**
 * In-app navigation for links inside rendered markdown.
 *
 * The docs and lesson markdown are written for GitHub, so they are full of
 * repo-relative links: `NOTES.md`, `lessons/03_constraint_propagation/README.md`,
 * `../../src/gridmind/board.py`. Left alone, clicking one navigates the SPA to a
 * path that does not exist, the dev server serves `index.html` from it, and every
 * relative `fetch()` then resolves against the wrong directory — which shows up as
 * "Could not load docs.json".
 *
 * So we intercept them and route to the right view instead. A link to a source
 * file opens it in the Code tab; a link to a lesson opens that lesson; a link to
 * a top-level doc switches documents. External links open in a new tab.
 */

export type ViewName = "solver" | "lessons" | "docs" | "code";

export interface Target {
  view: ViewName;
  /** Doc filename, lesson number, or source path — depending on the view. */
  ref?: string;
}

type Handler = (target: Target) => void;

let handler: Handler | null = null;

export const setNavigationHandler = (fn: Handler): void => {
  handler = fn;
};

export const goTo = (target: Target): void => handler?.(target);

const CODE_PREFIXES = ["src/", "web/", "tests/", "tools/"];
const DOC_FILES = new Set(["README.md", "NOTES.md", "COMMANDS.md", "CURRICULUM.md"]);

/**
 * Resolve a markdown href against the document it appeared in.
 *
 * `base` is the repo-relative directory of the containing document, e.g.
 * `lessons/01_board_representation/` — needed so `../../src/...` resolves.
 * Returns null when the link should be left to the browser.
 */
export function resolveHref(href: string, base = ""): Target | null {
  if (/^[a-z]+:/i.test(href) || href.startsWith("//")) return null;
  if (href.startsWith("#")) return null;

  // A dummy origin lets the URL parser do the ../ resolution for us.
  let path: string;
  try {
    const url = new URL(href, `https://repo.invalid/${base}`);
    path = decodeURIComponent(url.pathname).replace(/^\//, "");
  } catch {
    return null;
  }
  if (path === "") return null;

  const lesson = /^lessons\/(\d{2})_[^/]+\/(README|THEORY)\.md$/i.exec(path);
  if (lesson) return { view: "lessons", ref: lesson[1] };

  const lessonRun = /^lessons\/(\d{2})_[^/]+\/run\.py$/i.exec(path);
  if (lessonRun) return { view: "code", ref: path };

  if (DOC_FILES.has(path)) return { view: "docs", ref: path };

  if (CODE_PREFIXES.some((prefix) => path.startsWith(prefix))) {
    return { view: "code", ref: path };
  }

  return null;
}

/**
 * Intercept clicks on links inside `container`.
 *
 * Anything we cannot route in-app is either opened in a new tab (external) or
 * suppressed (a repo path with no view), rather than being allowed to break the
 * page. Call this after every markdown render.
 */
export function attachLinkHandler(container: HTMLElement, base = ""): void {
  for (const anchor of container.querySelectorAll<HTMLAnchorElement>("a[href]")) {
    const href = anchor.getAttribute("href") ?? "";

    if (/^https?:/i.test(href)) {
      anchor.setAttribute("target", "_blank");
      anchor.setAttribute("rel", "noopener noreferrer");
      continue;
    }
    if (href.startsWith("#")) continue;

    const target = resolveHref(href, base);
    anchor.addEventListener("click", (event) => {
      event.preventDefault();
      if (target !== null) {
        goTo(target);
      } else {
        // A repo path with nowhere to go — say so rather than navigating away
        // and breaking every relative fetch on the page.
        anchor.classList.add("dead-link");
        anchor.title = `${href} is not viewable in the app`;
      }
    });
    if (target === null) anchor.classList.add("dead-link");
  }
}

:root {
  --bg: #ffffff;
  --fg: #14161a;
  --muted: #666f7a;
  --line: #c9ced6;
  --line-strong: #3d434c;
  --given: #14161a;
  --derived: #2563c9;
  --branch: #b4531a;
  --highlight: #fff3d4;
  --conflict: #ffd9d9;
  --panel: #f6f7f9;
  --accent: #2563c9;
  --link: #a34a12;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --fg: #e8eaed;
    --muted: #9aa3ae;
    --line: #333942;
    --line-strong: #79818d;
    --given: #e8eaed;
    --derived: #6fa5ff;
    --branch: #ffab6b;
    --highlight: #3a3520;
    --conflict: #4a2222;
    --panel: #1c1f25;
    --accent: #6fa5ff;
    --link: #ffab6b;
  }
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 2rem 1rem;
  background: var(--bg);
  color: var(--fg);
  line-height: 1.5;
}

main { max-width: 60rem; margin: 0 auto; }

h1 { margin: 0; font-size: 1.6rem; letter-spacing: -0.02em; }
.subtitle { margin: 0.25rem 0 1.5rem; color: var(--muted); }

.layout {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  align-items: flex-start;
}

.grid {
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  width: min(28rem, 90vw);
  aspect-ratio: 1;
  border: 2px solid var(--line-strong);
  background: var(--line);
  gap: 1px;
}

.cell {
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: clamp(1rem, 3.4vw, 1.5rem);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  user-select: none;
  position: relative;
  transition: background-color 120ms ease;
}

.cell:nth-child(9n + 4), .cell:nth-child(9n + 7) {
  border-left: 2px solid var(--line-strong);
}
/* Heavy rules below rows 2 and 5 (0-indexed), i.e. 1-indexed cells 19-27
   and 46-54. Getting these off by one row is easy and very visible. */
.cell:nth-child(n + 19):nth-child(-n + 27),
.cell:nth-child(n + 46):nth-child(-n + 54) {
  border-bottom: 2px solid var(--line-strong);
}

.cell.given { font-weight: 650; color: var(--given); }
.cell.derived { color: var(--derived); }
.cell.branch { color: var(--branch); font-style: italic; }
.cell.selected { background: var(--highlight); }
.cell.active { background: var(--highlight); }
.cell.conflict { background: var(--conflict); }

.cell .candidates {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  font-size: 0.5rem;
  line-height: 1.1;
  color: var(--muted);
  width: 100%;
  height: 100%;
  padding: 2px;
}
.cell .candidates span { text-align: center; }

.panel {
  flex: 1 1 18rem;
  min-width: 16rem;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  padding: 1rem;
}

.field { display: block; margin-bottom: 0.75rem; }
.field span { display: block; font-size: 0.8rem; color: var(--muted); margin-bottom: 0.25rem; }

textarea {
  width: 100%;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.75rem;
  padding: 0.5rem;
  border: 1px solid var(--line);
  border-radius: 0.25rem;
  background: var(--bg);
  color: var(--fg);
  resize: vertical;
}

.buttons { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 0.75rem; }

button {
  font: inherit;
  font-size: 0.85rem;
  padding: 0.4rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: 0.25rem;
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
}
button:hover { border-color: var(--line-strong); }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }

.toggle { display: flex; align-items: center; gap: 0.5rem; font-size: 0.85rem; margin-bottom: 0.75rem; }

.samples { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; font-size: 0.85rem; color: var(--muted); }

.stats {
  margin: 1rem 0 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.75rem;
  white-space: pre-wrap;
  color: var(--muted);
  min-height: 5rem;
}

.hint { font-size: 0.8rem; color: var(--muted); margin-top: 0.75rem; }

/* --- view switching -------------------------------------------------------- */

.views { display: flex; gap: 0.5rem; margin-bottom: 1.5rem; border-bottom: 1px solid var(--line); }
.view {
  border: none; border-bottom: 2px solid transparent; border-radius: 0;
  background: none; padding: 0.5rem 0.9rem; font-size: 0.95rem; color: var(--muted);
}
.view.active { color: var(--fg); border-bottom-color: var(--accent); font-weight: 600; }
.hidden { display: none !important; }

/* --- lesson browser -------------------------------------------------------- */

.lessons { display: flex; gap: 2rem; align-items: flex-start; flex-wrap: wrap; }

.lesson-nav {
  flex: 1 1 20rem; min-width: 17rem; max-height: 80vh; overflow-y: auto;
  border: 1px solid var(--line); border-radius: 0.5rem; padding: 0.75rem; background: var(--panel);
}

.kind-summary { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-bottom: 0.75rem; }

.stage-heading {
  font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--muted); margin: 1rem 0 0.4rem;
}
.stage-heading:first-of-type { margin-top: 0; }

.lesson-list { list-style: none; margin: 0; padding: 0; }

button.lesson {
  display: flex; align-items: center; gap: 0.5rem; width: 100%; text-align: left;
  border: none; background: none; padding: 0.3rem 0.4rem; border-radius: 0.25rem;
  font-size: 0.85rem; color: var(--fg);
}
button.lesson:hover { background: var(--highlight); }
button.lesson.active { background: var(--highlight); font-weight: 600; }
button.lesson .num { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 0.75rem; }
button.lesson .lesson-title { flex: 1; }

.kind {
  font-size: 0.62rem; padding: 0.08rem 0.35rem; border-radius: 0.6rem;
  border: 1px solid var(--line); color: var(--muted); white-space: nowrap;
}
.kind-ml { border-color: #6fa5ff; color: #4a86e8; }
.kind-ai { border-color: #7cc47c; color: #4a9a4a; }
.kind-cv { border-color: #d98cd9; color: #b060b0; }
.kind-web { border-color: #f0b45a; color: #c07f1a; }

.lesson-content { flex: 2 1 26rem; min-width: 18rem; }

.tabs { display: flex; gap: 0.4rem; margin-bottom: 0.75rem; }
.tab { font-size: 0.85rem; }
.tab.active { background: var(--accent); border-color: var(--accent); color: #fff; }

.runline {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.75rem;
  background: var(--panel); border: 1px solid var(--line); border-radius: 0.25rem;
  padding: 0.5rem 0.6rem; overflow-x: auto; color: var(--muted); margin: 0 0 1rem;
}

.markdown { font-size: 0.92rem; }
.markdown h1 { font-size: 1.3rem; margin-top: 0; }
.markdown h2 { font-size: 1.05rem; margin-top: 1.5rem; }
.markdown h3 { font-size: 0.95rem; }
.markdown code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.85em;
  background: var(--panel); padding: 0.1em 0.3em; border-radius: 0.2em;
}
.markdown pre {
  background: var(--panel); border: 1px solid var(--line); border-radius: 0.3rem;
  padding: 0.7rem; overflow-x: auto;
}
.markdown pre code { background: none; padding: 0; }
.markdown table { border-collapse: collapse; width: 100%; font-size: 0.85rem; display: block; overflow-x: auto; }
.markdown th, .markdown td { border: 1px solid var(--line); padding: 0.35rem 0.5rem; text-align: left; }
.markdown blockquote { border-left: 3px solid var(--line); margin-left: 0; padding-left: 0.8rem; color: var(--muted); }

/* --- code browser ---------------------------------------------------------- */

.code-filter {
  width: 100%; font: inherit; font-size: 0.8rem; padding: 0.35rem 0.5rem;
  margin-bottom: 0.5rem; border: 1px solid var(--line); border-radius: 0.25rem;
  background: var(--bg); color: var(--fg);
}

.code-path {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.75rem;
  word-break: break-all;
}

.code-view {
  display: flex; gap: 0.75rem; border: 1px solid var(--line); border-radius: 0.3rem;
  background: var(--panel); padding: 0.7rem; overflow-x: auto; max-height: 75vh;
  overflow-y: auto;
}
.code-view pre {
  margin: 0; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.75rem; line-height: 1.5;
}
.code-view .gutter {
  text-align: right; color: var(--muted); user-select: none;
  border-right: 1px solid var(--line); padding-right: 0.75rem; flex: none;
}
.code-view .code-body { white-space: pre; color: var(--fg); }

/* --- editor (Code tab) ----------------------------------------------------- */

.editor-tabs {
  display: flex; gap: 1px; overflow-x: auto; background: var(--line);
  border: 1px solid var(--line); border-bottom: none;
  border-radius: 0.3rem 0.3rem 0 0;
}
.editor-tab { display: flex; align-items: center; background: var(--panel); flex: none; }
.editor-tab.active { background: var(--bg); }
.editor-tab-label {
  border: none; background: none; border-radius: 0; padding: 0.35rem 0.3rem 0.35rem 0.6rem;
  font-size: 0.75rem; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--muted); white-space: nowrap;
}
.editor-tab.active .editor-tab-label { color: var(--fg); }
.editor-tab-close {
  border: none; background: none; border-radius: 0; padding: 0.35rem 0.5rem 0.35rem 0.2rem;
  font-size: 0.85rem; line-height: 1; color: var(--muted);
}
.editor-tab-close:hover { color: var(--fg); }

.editor-host {
  height: 70vh; min-height: 22rem; overflow: hidden;
  border: 1px solid var(--line); background: var(--bg);
}
.editor-host .cm-editor { height: 100%; }
.editor-host .cm-editor.cm-focused { outline: none; }

.editor-status {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 0.7rem;
  color: var(--muted); background: var(--panel);
  border: 1px solid var(--line); border-top: none;
  border-radius: 0 0 0.3rem 0.3rem; padding: 0.35rem 0.6rem; overflow-x: auto;
  white-space: nowrap;
}


/* Links inside rendered markdown. The browser default blue fails contrast on
   the dark background, so both themes use an orange tuned for their own
   background rather than one colour that only works on one. */
.markdown a {
  color: var(--link);
  text-decoration: underline;
  text-underline-offset: 0.15em;
  text-decoration-thickness: 1px;
}
.markdown a:hover { text-decoration-thickness: 2px; }
.markdown a:focus-visible { outline: 2px solid var(--link); outline-offset: 2px; }
.markdown a.dead-link {
  color: var(--muted);
  text-decoration: line-through dotted;
  cursor: help;
}

/* --- puzzle picker --------------------------------------------------------- */

select {
  width: 100%; font: inherit; font-size: 0.85rem; padding: 0.4rem 0.5rem;
  border: 1px solid var(--line); border-radius: 0.25rem;
  background: var(--bg); color: var(--fg);
}

.puzzle-meta {
  margin: 0 0 0.75rem; font-size: 0.78rem; color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}
.puzzle-meta .tag {
  display: inline-block; border: 1px solid var(--line); border-radius: 0.6rem;
  padding: 0.05rem 0.4rem; margin-right: 0.3rem;
}
.puzzle-meta .tag.search { border-color: var(--branch); color: var(--branch); }

.custom { margin-top: 0.75rem; font-size: 0.85rem; }
.custom summary { cursor: pointer; color: var(--muted); }
.custom textarea { margin: 0.5rem 0; }
